  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--space-12);
}

.page--design-system .evaluated-catalog-scope .hero-signal, .page--labs-benchmark .hero-signal {
  min-height: 118px;
  padding: var(--space-18);
  border: 1px solid var(--border);
  border-radius: var(--radius-card);
  background: var(--surface-card);
  box-shadow: var(--shadow-sm);
}

.page--design-system .evaluated-catalog-scope .hero-signal span,
.page--labs-benchmark .hero-signal span,
.page--design-system .evaluated-catalog-scope .evaluation-context span,
.page--design-system .evaluated-catalog-scope .metric-card span,
.page--labs-benchmark .evaluation-context span,
.page--labs-benchmark .metric-card span {
