.page--design-system .evaluated-catalog-scope .hero-signal small, .page--labs-benchmark .hero-signal small {
  display: block;
  margin-top: var(--space-2);
  font: 600 var(--text-xxs-font-size)/var(--text-xxs-line-height) var(--font-mono);
}

.section--benchmark, .page--design-system .evaluated-catalog-scope .section--benchmark {
  padding: var(--space-72) 0;
  border-bottom: 1px solid var(--border);
}

.section-head--benchmark, .page--design-system .evaluated-catalog-scope .section-head--benchmark {
  align-items: end;
  margin-bottom: var(--space-24);
}

.page--design-system .evaluated-catalog-scope .section-title-wrap,
.page--labs-benchmark .section-title-wrap {
