  font-size: var(--text-xs-font-size);
}

.page--design-system .evaluated-catalog-scope .leaderboard td strong,
.page--labs-benchmark .leaderboard td strong {
  color: var(--text-strong);
  font-weight: var(--weight-semibold);
}

.page--design-system .evaluated-catalog-scope .rank, .page--labs-benchmark .rank {
  width: 34px;
  height: var(--space-28);
  display: grid;
  place-items: center;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--surface-card);
  font: 600 11px/1 var(--font-mono);
  color: var(--text-strong);
}

.page--design-system .evaluated-catalog-scope .provider-cell, .page--labs-benchmark .provider-cell {
  display: flex;
  align-items: center;
  gap: var(--space-10);
}

.page--design-system .evaluated-catalog-scope .provider-avatar, .page--labs-benchmark .provider-avatar {
  width: var(--space-30);
  height: var(--space-30);
