  place-items: center;
  border-radius: var(--radius-md);
  background: var(--surface-raised);
  /* The chip is always the raised dark surface, so the fallback ink has to hold
     on it: --violet is the 500, which measured 1.95:1 there. The 300 is the
     step that reads, and it only applies where a provider sets no tone. */
  color: var(--provider, var(--mindset-violet-300));
  font: 700 10px/1 var(--font-mono);
}


.page--design-system .evaluated-catalog-scope .count-chip, .page--labs-benchmark .count-chip {
  display: inline-flex;
