.page--design-system .evaluated-catalog-scope .segmented button, .page--labs-benchmark .segmented button {
  min-height: var(--space-32);
  padding: 0 var(--space-10);
  border: 1px solid var(--border);
  border-radius: var(--radius-control);
  background: var(--surface-card);
  color: var(--muted);
  font-size: var(--text-xs-font-size);
  font-weight: var(--weight-semibold);
}

.page--design-system .evaluated-catalog-scope .segmented button:hover,
.page--labs-benchmark .segmented button:hover {
