.page--design-system .evaluated-catalog-scope .chart-tooltip,
.page--labs-benchmark .chart-tooltip,
.page--partner-analysis .chart-tooltip {
  position: absolute;
  z-index: 5;
  border: 1px solid var(--border-strong);
  color: var(--text);
  box-shadow: var(--shadow-md);
  pointer-events: none;
  opacity: 0;
}

.page--design-system .evaluated-catalog-scope .chart-tooltip,
.page--labs-benchmark .chart-tooltip {
  min-width: 176px;
  padding: var(--space-10) var(--space-12);
  border-radius: var(--radius-lg);
  background: var(--surface-card);
  transform: translate(-50%, -112%);
  transition: opacity var(--duration-fast);
}

.page--design-system .evaluated-catalog-scope .chart-tooltip.is-visible,
.page--labs-benchmark .chart-tooltip.is-visible {
