.page--design-system .evaluated-catalog-scope .chart-tooltip span,
.page--labs-benchmark .chart-tooltip span {
  display: block;
  margin-top: var(--space-2);
  color: var(--muted);
  font: 500 var(--text-xxs-font-size)/var(--text-xxs-line-height) var(--font-mono);
