}

.page--docs-refresh .endpoint-details { display: none; padding: 0 var(--space-18) var(--space-18); }
.page--docs-refresh .endpoint-meta-grid { margin-bottom: var(--space-12); }
.page--docs-refresh .endpoint-meta-box { padding: var(--space-10); border-radius: var(--radius-md); }
.page--docs-refresh .endpoint-meta-box span { font: 600 8px/13px var(--font-mono); }
.page--docs-refresh .endpoint-meta-box strong { margin-top: var(--space-4); }
/* One data-table contract for both documentation applications; only the
   minimum table width differs. */
.page--docs-refresh .table-wrap,
.page--docs-v2 .table-wrap { overflow: auto; }
.page--docs-refresh table,
.page--docs-v2 table { border-collapse: collapse; }

.page--docs-refresh table { min-width: 680px; }
.page--docs-refresh :is(td, th),
.page--docs-v2 :is(td, th) { padding: var(--space-12) var(--space-14); vertical-align: top; }
.page--docs-refresh th,
.page--docs-v2 th { font: 650 9px/15px var(--font-mono); }


/* Both documentation applications end an article in .sp-footer--pager, which
