  --border-hover: color-mix(in srgb, var(--deep-navy-25) 20%, transparent);
  --container: 1280px;
  background: var(--deep);
  overflow-x: hidden;
}

html:has(> .page--homepage) {
  scroll-behavior: smooth;
  scroll-padding-top: var(--space-88);
  overflow-x: hidden;
}

.page--homepage a { color: inherit; }
.page--homepage img { max-width: 100%; }
.page--homepage ::selection { background: var(--mindset-violet-200); color: var(--deep); }
.page--homepage :focus-visible { outline: 2px solid var(--mindset-violet-400); outline-offset: 3px; }
.page--design-system .sp-popup-preview-head span,
.page--design-system .panel-surface-rule code,
.page--docs-refresh .hero-meta,
.page--docs-refresh td code,
.page--homepage .live-status { font: 500 var(--text-xxs-font-size)/var(--text-xxs-line-height) var(--font-mono); }

.page--homepage .live-status i {
  width: var(--space-6);
  height: var(--space-6);
  background: var(--green);
  animation: homepage-pulse 1.8s infinite;
}

.page--homepage .target {
  width: var(--space-28);
  height: var(--space-28);
  border: 2px solid var(--pink);
  animation: homepage-targetmove 6s ease-in-out infinite;
}

.page--homepage .target::after, .page--homepage .target::before {
  content: "";
  position: absolute;
  background: var(--pink);
}

.page--homepage .target::before {
  width: var(--space-12);
  height: var(--space-2);
  left: var(--space-6);
  top: var(--space-10);
}

.page--homepage .target::after {
  width: var(--space-2);
  height: var(--space-12);
  left: var(--space-10);
  top: var(--space-6);
}

.page--homepage .game-meta {
  left: var(--space-16);
  right: var(--space-16);
  top: var(--space-16);
  font: 500 var(--text-xxs-font-size)/var(--text-xxs-line-height) var(--font-mono);
  letter-spacing: 0.06em;
}

.page--homepage .stat { padding: var(--space-22) var(--space-24); border-right: 1px solid var(--border); }
.page--homepage .stat:last-child { border-right: 0; }
.page--homepage .stat strong { font: 500 28px/34px var(--font-mono); letter-spacing: -0.035em; }
.page--homepage .stat span { margin-top: var(--space-4); }


.page--homepage .badge-card { width: 230px; }
.page--homepage .badge-card img { aspect-ratio: 1; object-fit: contain; }
.page--homepage .badge-card span { margin-top: var(--space-8); }

.page--homepage .footer-brand img { width: 170px; }
.page--homepage .footer-brand p { max-width: 360px; margin: var(--space-18) 0 0; }

.page--homepage .reveal {
  opacity: 0;
  transform: translateY(18px);
  transition: opacity var(--duration-slowest) ease, transform var(--duration-slowest) ease;
}

.page--homepage .reveal.is-visible { opacity: 1; transform: none; }


/* ---------------------------------------------------------------------------
   Card padding and heading rhythm, folded in from the marketing stylesheet

   The utility layer resets every heading with
   `.page :where(h1, h2, h3, h4) { margin: 0 }` and the composition never
   restores the per-component margins the approved design carried, so an
   icon tile, its title and its body copy read as one solid block. The
   same markup and the same defect exist on the prototype homepage, so
   these are not scoped to `.page--site`.
   --------------------------------------------------------------------------- */

html:not([data-reveal]) .page--site .reveal {
  opacity: 1;
  transform: none;
}
.page--homepage .section-head h2 { margin-bottom: var(--space-18); }

.page--homepage :is(.hero-copy, .profile-copy, .process-copy, .badge-copy, .cta-copy)
  :is(h1, h2) {
  margin-block: var(--space-18) var(--space-20);
}

/* ==========================================================================
   09 - Unique composition · Labs Benchmark
   ========================================================================== */

/* ---------------------------------------------------------------------------
   Hero and panel composition, restored from the approved page.

   Consolidation left this page relying entirely on shared defaults, which cost
   it three things the approved design had: a title that wraps, hero columns
   that are actually separated, and panels that are padded once.
   -------------------------------------------------------------------------- */

.page--labs-benchmark .hero--benchmark h1 {
  font-size: clamp(38px, 4.4vw, var(--display-xl-font-size));
  line-height: 1.08;
}

.page--labs-benchmark .hero-grid--benchmark { gap: var(--space-64); }

.page--labs-benchmark .sp-panel:has(> .panel-inner) { padding: 0; }

.page--labs-benchmark .leaderboard-sort {
  gap: var(--space-4);
  color: inherit;
  font: inherit;
  letter-spacing: inherit;
  text-transform: inherit;
  cursor: pointer;
}

.page--labs-benchmark .leaderboard-sort:hover { color: var(--text-strong); }

.page--labs-benchmark .filter-group .button-group { justify-self: start; }

.page--labs-benchmark .hero-signal:has(.button) small {
  color: var(--muted);
  font-family: var(--font-ui);
  font-size: var(--font-size-md);
  line-height: var(--text-sm-line-height);
}

.page--labs-benchmark .play-notes { margin-top: var(--space-12); color: var(--quiet); }

.page--labs-benchmark .methodology-section, .page--labs-benchmark .waitlist-section {
  padding: var(--space-72) 0;
}

.page--labs-benchmark .methodology-section article { padding: var(--space-28); background: var(--surface); }
.page--labs-benchmark .waitlist-section header { max-width: 680px; }
.page--labs-benchmark .waitlist-form { width: min(100%, 560px); padding: var(--space-28); }

/* The control geometry is the .field component's - 44px tall, 10/12 padding,
   the same on every Skillprint surface. This page used to set its own 12/14,
   which made the waitlist inputs a step taller than the arena selects directly
   above them. Only the textarea's own height is stated. */
.page--labs-benchmark .waitlist-form textarea { min-height: 110px; resize: vertical; }

/* A fieldset's label is a legend, so it needs the .field label contract
   spelled out - the component's own rule only reaches <label>. */
.page--labs-benchmark .waitlist-form legend {
  padding: 0;
  color: var(--surface-text);
  font-family: var(--skillprint-font-ui);
  font-size: var(--font-size-xs);
  line-height: var(--text-xs-line-height);
  font-weight: var(--weight-semibold);
}

.page--labs-benchmark .interest-options input { opacity: 0; }

.page--labs-benchmark .interest-options span {
  padding: var(--space-6) var(--space-12);
  background: var(--surface-card);
  color: var(--muted);
  transition: var(--transition-interactive);
}

.page--labs-benchmark .interest-options input:checked + span {
  border-color: var(--violet);
  color: var(--text-strong);
}

/* The input is opacity:0, so every ring it inherits - the :where() base, the
   .page outline, the .field glow - is painted at zero alpha and keyboard focus
   is invisible. Part A solves this for its own choice controls by projecting
   the ring onto the visible sibling (.radio-input:focus-visible +
   .radio-control); the pill does the same. Ring only, so the checked pill
   keeps its violet edge while focused. */
.page--labs-benchmark .interest-options input:focus-visible + span {
  box-shadow:
    0 0 0 var(--space-4)
      color-mix(
        in srgb,
        var(--mindset-violet-400) 24%,
        transparent
      );
}

.page--labs-benchmark .catalog-module .catalog__grid { align-items: stretch; }

.page--labs-benchmark .catalog-module .ability__icon {width: var(--space-16); height: var(--space-16); flex: 0 0 16px; opacity: 0.84;}

.page--labs-benchmark .primary-nav a.is-active,
.page--labs-benchmark .primary-nav a[aria-current="page"] {
  color: var(--text-strong);
}

html[data-surface="light"] > .page--labs-benchmark, html[data-theme="light"] > .page--labs-benchmark {
  --quiet: color-mix(in srgb, var(--geistface-grey-800) 50%, transparent);
  --page: var(--deep-navy-25);
  --surface: var(--panel-navy-50);
  --surface-card: var(--geistface-grey-25);
  --surface-raised: var(--geistface-grey-100);
}

/* In index.html the catalog module is a standalone preview frame, so it carries
   its own 32px gutter and a frame's worth of vertical padding. Here the same
   module is inline page content that already sits inside .sp-container and
   inside a .section--benchmark, so both were being applied twice: the cards
   stood 32px inside every other section on the page, and the section ran 136px
   of air above the heading and below the grid. The module gives all three back
   to the shell it is embedded in. */
.page--labs-benchmark .catalog-shell { padding-top: 0; }
.page--labs-benchmark .catalog-module .page { padding: 0; }

.page--labs-benchmark .catalog-module .catalog {
  width: 100%;
  max-width: none;
  margin: 0;
}

.page--labs-benchmark .catalog-module .catalog__grid { gap: var(--spacing-xl); }

.page--labs-benchmark .catalog-module .ability__icon svg,
.page--labs-benchmark .catalog-module .signal__icon svg {fill: currentColor;}
/* Both closing sections ran on their own rhythm - methodology on 96/96 and the
   waitlist on 0/96, which left the form hard against the section above it.
   They join the 72/72 cadence the rest of the page keeps. */
.page--labs-benchmark .methodology-section {
  padding-block: var(--space-72);
  border-top: 0;
  border-bottom: 1px solid var(--border);
}

.page--labs-benchmark .methodology-section article {
  padding: var(--spacing-4xl);
  border-radius: var(--radius-card);
}

.page--labs-benchmark .waitlist-section {
  padding-block: var(--space-72);
  border-top: 0;
}
.page--labs-benchmark .waitlist-section header { max-width: var(--grid-readable-max); }
.hero-copy,
.page--homepage .profile-copy > p, .page--homepage .process-copy p, .page--homepage .badge-copy p,
.page--labs-benchmark .waitlist-section header p { font-size: var(--text-lg-font-size); line-height: var(--text-lg-line-height); }

/* Two equal columns left the copy stranded at the top of a half-page column of
   nothing, because the row is as tall as the form. The copy column is narrower
   now and sticks beside the form as it scrolls, so the empty space reads as
   deliberate margin rather than a gap someone forgot to fill. */
.page--labs-benchmark .waitlist-section .sp-container {
  grid-template-columns: minmax(0, 0.8fr) minmax(0, 1fr);
  gap: var(--space-72);
}

.page--labs-benchmark .waitlist-section header {
  position: sticky;
  top: var(--space-96);
}

.page--labs-benchmark .waitlist-section .waitlist-form { width: 100%; }

.page--labs-benchmark .waitlist-form {
  padding: var(--spacing-4xl);
  background: var(--surface);
  box-shadow: var(--shadow-xs);
}

